"""Shared S1 AI prompt prefixes and cache-oriented message assembly.

These prefixes intentionally repeat only stable rules that already exist in the
task-specific prompts. Keeping them byte-identical at the beginning of related
requests improves DeepSeek prefix-cache hits without changing output schemas.
"""
import hashlib
import json
S1_EXPEDITION_STORY_COMPLETION_RULE = '【深渊酒馆·单次探险的故事边界】\n- 一次探险交付一场完整故事，覆盖出发、探索与冲突的实际推进、本场结果及返程。已提供的出发片段直接承接，不重复开场；篇幅安排须为决定结果的过程与返程留下空间，不能把本次主线停在新的行动起点，等待下一次冒险补完。\n- 正常能够归队的幸存成员在正文中完成离场与返回酒馆；决定撤离、开始返程不等于已经返回。返程可以简洁，但须承接已经成立的脱离条件、成员处境与成果处置，不能只加一句回到酒馆来跳过尚未解决的当前行动。\n- 本场失败、放弃目标或撤退也须形成完整结果，不强制胜利、收益或消灭仍然存在的威胁。已经成立的死亡、失踪及其它无法归队的权威结果如实收束，不为返程复活成员或补造脱险；无人生还时，以已发生的终局结束本场。已成立的失踪本身可以作为该成员本场终点，不要求揭示未知去向。\n- 完整性针对整场最终 events，不要求每一条事件、内部中段或分批展示片段各自完结。长期世界问题和背景未知可以保留，但本场实际承担的行动结果、成员最终处境与离场终点不能悬置；后续世界仍可发展，不把本场写成后续探险的序章。'
S1_EXPEDITION_SCORE_RULE = '【成员表现评分】\n每名成员的 score 是本场个人表现分，取 0–10 范围内的有限数值，可以有小数。依据成员当时可知的信息、可用能力、实际选择与执行、对本场结果的实际贡献评价，以 5 分为通常表现的中点；它不是金币、经验、属性成长或生命值。没有成长或收益不等于零分，生还、死亡、胜负与撤离也不单独决定评分；0 分只表达实际表现处于最低端。逐成员依据已经发生的正文评价，评分不反向决定剧情或要求成员展示资产。'
S1_EXISTING_ATTRIBUTE_SCALE_RULE = '【深渊酒馆·当前属性与画像尺度】\n- 力量、敏捷、智力、幸运分别以 200 作为普通人类的属性上限参照。特别强大的个体或已突破人类极限的实体，可以按自身设定和实际实力在相关属性上超过 200，各项能力分别成立。最大生命与当前生命使用独立尺度，血量不套用这个 200 参照。\n- 成员真实属性已经包含其既往成长，同级成员的实际能力可以明显不同。画像五维以 basis_level 对应的常规冒险者为共同尺度，baseline 表示该层级常规水平；实际交互沿双方具体本领、当前状态和作用边界形成，等级与档位不单独裁决胜负。'
S1_CORE_LEVEL_AND_ATTRIBUTE_REFERENCE_RULE = '【深渊酒馆·核心基础等级与属性尺度】\n- 地牢推荐等级描述当地常规生态，不是本场全部主体的实力上限。尚未定义的主要对抗主体使用本次新核心参照；未被核心强化的原生伴生生态沿地点等级，已有主体沿准确身份与能力版本。命途试炼、共同挑战等已提供独立参照时，按该合同的作用范围采用，不由通用新核心参照覆盖。\n- 新核心的基础等级由后端取队伍最高等级与地牢等级下限的较高值，再加本次模式配置的提升。特殊事件与隐藏Boss同时触发时，取两者提升中的较高值，应用一次。user 中 core_level_reference.basis_level 是最终等级，special_core_basis_level 在提供时表达同一结果，按该值填写新核心的 basis_level。它只给出共同尺度，具体本领还须达到当前模式对这支实际队伍的强度要求。\n' + '\n' + S1_EXISTING_ATTRIBUTE_SCALE_RULE
S1_NEW_CORE_STRENGTH_CALIBRATION_RULE = '【深渊酒馆·新核心实力定义】\n只在创作尚无权威画像的主要对抗主体时校准实力。红黑本先按这支队伍正常发挥所需承受的有效打击与反击规模，确定新主体自身需要具备的实力，再结合当前地点、目标和世界事实建立相容的身份、目的与本领。场景材料说明相遇的来源，不替代实力校准。成员资料只确立对应持有者的能力和当前状态；其中记载的外部对象不因此在本场出现，也不因此取得能力或弱点。其它主体知情仍须有自身已获得的信息。\n红黑本的难度参照是这支队伍作为整体正常发挥后的战斗承受能力，按各自模式建立足以致命的压力；黑本主要对抗主体对整队保持不可战胜。谁存活由实际交锋决定，其它模式沿自身要求。\n新核心自身使用与成员相同的生命尺度，在 capabilities 中给出完整生命承受量（HP）及其真实防护、恢复边界。红本主体须能承受整队正常反击并继续交锋；黑本主体承受本队现有手段连续作用的累计破坏后，仍须保持压倒性的作战能力。承受规模在创建时建立，不在受创后补满，也不预写本场实际命中或损耗。\n红黑本的 capabilities 至少建立一项能在常态交锋中反复实施的主要攻击。校准时先把本队现有且适用的防护、支援与恢复计入，再比较完整接触后的净生命损失：净损失达到其实际受作用成员的 max_hp，才达到普通生命损伤的致命规模；只达到受伤成员的 current_hp 或无防护时的生命上限，均未完成校准。同时按整队在这个作用时段内可完成的反击核对主体自身承受量；承受这些反击与局部打断后仍能完成该主要攻击，才达到持续作战要求。条件未成立时，先完善主体自身相容的施力、承受与作用条件，再交付；再次发动次数多不替代本次有效打击规模。这里建立能力，不预定本场实际命中、人员生死或胜负，真实行动仍改变接触与承受。其它模式沿自身强度要求。limitations 记录与本领相容的固有边界，不预写队伍解法。\n红黑本新核心会造成普通生命损伤的本领，在同一条 capabilities 中明确完整作用于单个无防护目标时的基础 HP 损耗，以及对应的单次接触或持续时段。这是该能力自身的效力，随主体基础等级、实际力量和作用机制确定；对不同目标保持同一尺度，实际接触程度、防护与恢复再改变承受结果。同一条能力同时交代实际到达方式、覆盖范围和生效时段。持续作用分别说明发动所需条件、已施加作用的维持条件与结束条件；它是否随施用者动作中断而停止，由自身维持条件确定。即时作用完成后不再继续施加该次作用，已经造成的状态仍沿自身条件保持；持续作用只在原维持条件仍成立的时间内继续，两者都按自身实际功能定义，不为所有能力附加持续性。多人总损耗不作为每人损耗，不预写命中、减免或剩余生命。非伤害能力仍按自身功能定义，已有主体沿用原版本，不追填这项新定义。\n本领来自主体自身的身体、修习、经历与资源，同样条件对其它对象同样成立，不按某个成员身份强制其能力失效。已有主体继续沿准确版本与真实变化，不按本场难度重写。输出只建立主体自身的能力与边界，不预写队伍动作、解法、交锋顺序或人员结果；进入交锋后沿已成立定义推演，不再为结果追加本领。'
S1_ENCOUNTER_DEFINITION_BOUNDARY = '【深渊酒馆·交锋前能力定义】\n服务端提供 encounter_definition.schema_version=1 时，同一大纲的 encounter_capability_profiles 是交锋开始前已建立的主体能力。新主体采用该定义，已有长期主体仍以准确 ID/能力版本的冻结档案为准；当前世界事实、模式硬边界与使用权限保持原优先级。画像只确立本领、作用条件和固有限制，不证明实际接触、胜负、生死或实力合格，也不要求每个主体都出场。\n画像中的 identity_summary、current_agenda 分别承载开场身份和当前目的、行动，供理解同一主体如何参与现场；它们不授予额外本领、角色知识、长期身份或写入权限。当前目的不是固定行动脚本，主体可依据随后实际取得的信息与处境变化作出新选择。历史画像缺少这两项时沿用已提供事实，不据此补造经历或意图。\n能力的生效、维持与恢复沿已有定义。判断一处变化能否削弱另一处作用，先确定后者是否必须依赖前者；这种必要关系须来自已有能力定义或该次行动前已经成立的物理事实。必要依赖成立且实际被破坏，才按它承担的部分削弱作用；必要依赖未成立，另一处作用保持原能力。暂时作用结束后，原生效条件仍满足的能力恢复原作用；只有另有独立成立的阻碍才继续受限，展开过程不追加恢复步骤或延长失能。获得力量的历史来源、唤醒过程与当前维持条件分别判断，原定义已内化为自身的力量按自身条件延续。既有本领的新运用、对目标的发现及作用依据统一沿【深渊酒馆·双方能力作用边界】成立。人物只知道自己已获知的信息，创作者用于校准新核心的成员资料不成为其它主体的已知情报。\n没有该服务端标记的历史大纲仍是创作候选。能力画像不是封闭出场名册，空数组只表示大纲没有定义新主体。首次交互涉及尚无定义的主体时，由主剧情先建立相容能力。已触发特殊事件或 active 隐藏Boss时，若已生成的大纲未提供本场核心或已有主体不足以承担当前模式，主剧情负责在首次交互前，于世界事实允许的空白中建立符合模式的新核心及其具体能力；已有主体保持原版本。进入交互后沿已成立定义和真实变化继续，结果不反向改写能力。'
_S1_SPECIAL_EVENT_STORY_COMPLETION = '；大纲未完成的核心定义由正文按【深渊酒馆·交锋前能力定义】补足'
_S1_SPECIAL_EVENT_MODE_INTRO = f'【特殊事件·模式身份与强度优先级】\n仅在本次服务端类别不是 normal 时生效：本场须实际建立当前模式的核心，满足其来源、强度与作用范围，再按双方真实能力、接触与状态裁决应对效果。大纲负责建立开场核心，正文负责让当前模式在本场实际成立{_S1_SPECIAL_EVENT_STORY_COMPLETION}。模式要求优先于创作候选与叙事偏好；已成立的世界事实、主体能力版本、人物知识和写入权限仍是硬边界。成员的真实属性、当前状态和压缩能力用于定义新核心的具体本领，行动、成败与后果沿世界时间形成。'
_S1_RED_SPECIAL_EVENT_MODE_RULES = {'local_anomaly': '- local_anomaly：高于当地常规生态的异常作用已进入当前地点，并实质改变本场核心推进条件；局部范围本身足以成立，不要求扩大为区域灾变。', 'regional_incident': '- regional_incident：异常的来源、牵连或传导已超出单一地点，区域联系必须通过当前地点的实际作用进入核心因果，不能仅在背景中宣称远方也受影响。', 'world_fact_catalyst': '- world_fact_catalyst：本地核心具备改变公共世界后续走向的实际因果条件，这种联系须体现在本场作用或目标条件中；是否推进既有公共线、形成新事实及其最终范围，仍由正文事实和冻结授权决定。没有宏观写权限时只落实本地作用与已成立联系，不预写远方变化，不为兑现类别开启 world_state_change_allowed。', 'extreme_crisis': '- extreme_crisis：新增核心的整体压力超出当地常规生态通常能够处理的层级，具备使常规应对不足的实际机制；本队是否能够处理仍由其已有实力与实际交互决定，不自动取得不可战胜性。'}
S1_RED_SPECIAL_EVENT_KINDS = frozenset(_S1_RED_SPECIAL_EVENT_MODE_RULES)
_S1_HIGH_RISK_STORY_COMPLETION = '大纲只提供中立角色或敌对目标不足时，正文在成员首次行动前，从世界事实容许的未定义空间补足敌对主体及具体能力，沿用既有角色原状。'
S1_HIGH_RISK_COMBAT_FOCUS_RULE = f'【红黑事件·战斗重心】\n仅在本次为四类红色特殊事件或 unbeatable_horror 时适用：本场必须实际发生战斗，并以战斗为主线。开场已有主体沿自身目的主动施加能够到达队伍的敌对作用，完整作战本领足以对这支队伍造成当前模式要求的致命压力；是否命中与造成何种结果由实际交锋形成。仅有强者在场或等待队伍另行触怒，不构成这场冲突。围绕原有探险目标展开这场对抗，具体实力按【深渊酒馆·新核心实力定义】校准。\n本场至少有一位实际参与的长期实体，具有可持续识别的身份、自主目的与自身本领。沿用已有角色时采用准确身份与版本；新角色在 individual 画像中建立稳定 subject、identity_summary 和 current_agenda，承载本场相遇及离场后可继续追踪的自身生活。存续与死亡由实际交互决定，长期身份不授予生还保证。\n已有角色保持既定立场与能力。中立角色照常参与剧情，本场敌对目标同时成立；强者的存在与可怕本领本身不代替敌对冲突。大纲负责交付敌对主体、动机与本领；正文负责交付实际成立的红黑遭遇。{_S1_HIGH_RISK_STORY_COMPLETION}\n正文从已成立的敌对作用进入实际交锋，沿双方行动和完整能力改变处境，主线推进与结尾由战斗进程形成。各方按自身目标、所得信息与真实条件持续行动；人物交流与信息发现只服务交战中的判断和行动，调查、交涉与合作解题不替代战斗主线。\n战斗中的规避、脱离和局部成功按真实条件形成；交锋长度、生还与伤亡由过程决定。unbeatable_horror 的敌对核心同时执行【绝对死境·核心不可战胜边界】。'
_S1_RED_PRESSURE_BASELINE = '红色特殊事件以本次队伍正常发挥仍面对足以造成成员死亡的实质压力'
_S1_RED_PRESSURE_CURRENT = '核心主体的完整作战能力承担这种压力：队伍识破或应对局部机制后，该主体其余本领仍能在实际战斗中形成有效接触与致命后果。'
_S1_RED_PRESSURE_OUTCOME = '红本允许队伍凭实力与行动取得整体胜利；危险何时解除，由核心主体剩余能力、行动条件与战斗实际进程共同决定，局部奏效只改变它真正作用到的部分。队伍等级超过地图不解除该要求，局部作用范围也不等于低强度。事件来源和当前世界事实解释这种实力为何在此参与；已成立主体保持原能力。'
_S1_RED_SPECIAL_EVENT_PRESSURE = _S1_RED_PRESSURE_BASELINE + '为生成基线，具体本领按【深渊酒馆·新核心实力定义】校准。' + _S1_RED_PRESSURE_CURRENT + '创作新核心时以队伍正常运用已有手段后的整体对抗为强度参照，交付足以承受这种对抗并继续作战的主体。' + _S1_RED_PRESSURE_OUTCOME
_S1_SPECIAL_EVENT_CAPABILITY_BOUNDARY = '旧危机结束只证明该来源已经结束，局部安全只约束它明确覆盖的对象、范围和时点；本次特殊事件从其余相容的主体、来访与当前行动中建立新核心，不要求复活旧危机或预先改写地点现状。已有主体不足以承担当前模式时保留其原状；已定义主体按本领参与，实际有效的应对照实形成后果。'
_S1_SPECIAL_EVENT_OTHER_MODES = 'stranger 继续以异界规则不兼容及其关系影响为核心，abyss 继续以可继承的因果放大为核心；二者执行各自专项边界，不互相替代，也不自动成为绝对死境。unbeatable_horror 执行【绝对死境·核心不可战胜边界】。'
_S1_SPECIAL_EVENT_OUTCOME_BOUNDARY = '模式规定的相对实力是交锋前提，每次作用在此前提内判定。具体行动、局部得失、离场条件和成员生死由实际交互形成，不预定撤离成功或伤亡人数。红本的整体胜负可由交锋决定；黑本主要对抗主体对整队不可战胜，执行【绝对死境·核心不可战胜边界】。强度是否落实须看实际能力与交战过程，不以零死亡或返程生命值高低单独反推。'
S1_SPECIAL_EVENT_MODE_BOUNDARY = '\n'.join((_S1_SPECIAL_EVENT_MODE_INTRO, *_S1_RED_SPECIAL_EVENT_MODE_RULES.values(), _S1_RED_SPECIAL_EVENT_PRESSURE, S1_HIGH_RISK_COMBAT_FOCUS_RULE, _S1_SPECIAL_EVENT_CAPABILITY_BOUNDARY, _S1_SPECIAL_EVENT_OTHER_MODES + _S1_SPECIAL_EVENT_OUTCOME_BOUNDARY))

def build_s1_special_event_mode_boundary(special_event_type: str | None=None, *, for_outline: bool=False, for_resolution: bool=False, for_resource_review: bool=False) -> str:
    """Select the current mode; keep the full shared contract for legacy callers."""
    if for_resource_review:
        if special_event_type == 'normal':
            return ''
        blocks = []
        if special_event_type in S1_RED_SPECIAL_EVENT_KINDS:
            blocks.append(_S1_RED_PRESSURE_BASELINE + '为已冻结的模式要求。' + _S1_RED_PRESSURE_CURRENT + _S1_RED_PRESSURE_OUTCOME)
        if special_event_type == 'unbeatable_horror':
            blocks.append(S1_UNBEATABLE_HORROR_RELATIVE_STRENGTH_RULE)
        blocks.append(_S1_SPECIAL_EVENT_OUTCOME_BOUNDARY)
        return '\n'.join(blocks)
    if for_resolution:
        return build_s1_special_event_mode_boundary(special_event_type).replace('，具体实力按【深渊酒馆·新核心实力定义】校准。', '。').replace('，具体本领按【深渊酒馆·新核心实力定义】校准', '')
    if for_outline:
        return build_s1_special_event_mode_boundary(special_event_type).replace(_S1_SPECIAL_EVENT_STORY_COMPLETION, '').replace(_S1_HIGH_RISK_STORY_COMPLETION, '')
    if special_event_type == 'normal':
        return ''
    if special_event_type not in S1_RED_SPECIAL_EVENT_KINDS | {'stranger', 'abyss', 'unbeatable_horror'}:
        return S1_SPECIAL_EVENT_MODE_BOUNDARY
    blocks = [_S1_SPECIAL_EVENT_MODE_INTRO]
