def _compact_json(value) -> str:
    return json.dumps(value, ensure_ascii=False, separators=(',', ':'))

def _short_hash_text(value: str) -> str:
    return hashlib.sha256(value.encode('utf-8')).hexdigest()[:16]

def _safe_int(value) -> int:
    if isinstance(value, bool):
        return 0
    try:
        return int(value)
    except (TypeError, ValueError):
        return 0

def order_s1_data_appeal_party_roster(party_roster: list) -> list:
    """Return a prompt-only stable roster copy without changing backend order."""

    def _sort_key(row):
        if not isinstance(row, dict):
            return (2, _compact_json(row))
        raw_adventurer_id = row.get('adventurer_id')
        if isinstance(raw_adventurer_id, bool):
            return (1, _compact_json(row))
        try:
            return (0, int(raw_adventurer_id), _compact_json(row))
        except (TypeError, ValueError):
            return (1, _compact_json(row))
    return sorted(list(party_roster), key=_sort_key)

def order_s1_data_appeal_shared_evidence(payload: dict) -> dict:
    """Place the largest reusable evidence before mutable roster state."""
    ordered = {}
    if 'appeal_fact_sheet' in payload:
        ordered['appeal_fact_sheet'] = payload['appeal_fact_sheet']
    if 'expedition_evidence' in payload:
        ordered['expedition_evidence'] = payload['expedition_evidence']
    if 'party_roster' in payload:
        roster = payload['party_roster']
        ordered['party_roster'] = order_s1_data_appeal_party_roster(roster) if isinstance(roster, list) else roster
    ordered.update({key: value for key, value in payload.items() if key not in ordered})
    return ordered

def order_s1_data_appeal_expedition_evidence(evidence: dict) -> dict:
    """Place expedition-wide facts before appellant-specific evidence."""
    ordered = {key: evidence[key] for key in S1_DATA_APPEAL_EXPEDITION_COMMON_PREFIX_KEYS if key in evidence}
    ordered.update({key: value for key, value in evidence.items() if key not in ordered})
    return ordered

def build_s1_data_appeal_cache_diagnostics(*, shared_system_prompt: str, shared_evidence_payload: dict, shared_evidence_content: str | None=None) -> dict[str, str | int]:
    """Build non-sensitive hashes and sizes for cache-hit attribution."""
    ordered_payload = order_s1_data_appeal_shared_evidence(shared_evidence_payload)
    expedition_evidence = ordered_payload.get('expedition_evidence')
    expedition_evidence = expedition_evidence if isinstance(expedition_evidence, dict) else {}
    common_evidence = {key: expedition_evidence[key] for key in S1_DATA_APPEAL_EXPEDITION_COMMON_PREFIX_KEYS if key in expedition_evidence}
    party_roster = ordered_payload.get('party_roster')
    party_roster = party_roster if isinstance(party_roster, list) else []
    common_evidence_json = _compact_json(common_evidence) if common_evidence else ''
    expedition_evidence_json = _compact_json(expedition_evidence) if expedition_evidence else ''
    party_roster_json = _compact_json(party_roster) if party_roster else ''
    shared_evidence_json = shared_evidence_content if isinstance(shared_evidence_content, str) else _compact_json(ordered_payload)
    common_prefix_material = '\x00'.join((S1_DATA_APPEAL_CACHE_LAYOUT_VERSION, shared_system_prompt, common_evidence_json))
    return {'layout_version': S1_DATA_APPEAL_CACHE_LAYOUT_VERSION, 'expedition_log_id': _safe_int(common_evidence.get('expedition_log_id')), 'common_prefix_hash': _short_hash_text(common_prefix_material), 'shared_system_hash': _short_hash_text(shared_system_prompt), 'expedition_evidence_hash': _short_hash_text(expedition_evidence_json) if expedition_evidence_json else '', 'party_roster_hash': _short_hash_text(party_roster_json) if party_roster_json else '', 'shared_evidence_hash': _short_hash_text(shared_evidence_json), 'common_evidence_chars': len(common_evidence_json), 'expedition_evidence_chars': len(expedition_evidence_json), 'party_roster_chars': len(party_roster_json), 'shared_evidence_chars': len(shared_evidence_json)}

def log_s1_data_appeal_cache_diagnostics(logger, *, appeal_id: int, stage: str, shared_system_prompt: str, shared_evidence_payload: dict, shared_evidence_content: str) -> None:
    """Log cache-comparison metadata without logging evidence content."""
    diagnostics = build_s1_data_appeal_cache_diagnostics(shared_system_prompt=shared_system_prompt, shared_evidence_payload=shared_evidence_payload, shared_evidence_content=shared_evidence_content)
    logger.info('数据申诉共享证据前缀 appeal=%s stage=%s layout=%s expedition_log=%s common_prefix_hash=%s shared_system_hash=%s expedition_evidence_hash=%s party_roster_hash=%s shared_evidence_hash=%s common_evidence_chars=%s expedition_evidence_chars=%s party_roster_chars=%s shared_evidence_chars=%s', appeal_id, stage, diagnostics['layout_version'], diagnostics['expedition_log_id'], diagnostics['common_prefix_hash'], diagnostics['shared_system_hash'], diagnostics['expedition_evidence_hash'], diagnostics['party_roster_hash'], diagnostics['shared_evidence_hash'], diagnostics['common_evidence_chars'], diagnostics['expedition_evidence_chars'], diagnostics['party_roster_chars'], diagnostics['shared_evidence_chars'])

def build_s1_data_appeal_messages(*, shared_system_prompt: str, task_system_prompt: str, shared_evidence_payload: dict | None, task_user_prompt: str, shared_evidence_prefix_enabled: bool) -> list[dict[str, str]]:
    """Build an appeal request with shared evidence before role-specific rules.

    The cache layout is useful only when evidence exists. Disabling it, or calling
    without shared evidence, retains the established single-system layout.
    """
    evidence_content = None
    if shared_evidence_payload:
        evidence_payload = order_s1_data_appeal_shared_evidence(shared_evidence_payload) if shared_evidence_prefix_enabled else shared_evidence_payload
        evidence_content = _compact_json(evidence_payload)
    if shared_evidence_prefix_enabled and evidence_content is not None:
        return [{'role': 'system', 'content': shared_system_prompt}, {'role': 'user', 'content': evidence_content}, {'role': 'system', 'content': task_system_prompt}, {'role': 'user', 'content': task_user_prompt}]
    messages = [{'role': 'system', 'content': shared_system_prompt + task_system_prompt}]
    if evidence_content is not None:
        messages.append({'role': 'user', 'content': evidence_content})
    messages.append({'role': 'user', 'content': task_user_prompt})
    return messages
